const openPublicURLRecoveryEpisode = `-- name: OpenPublicURLRecoveryEpisode :exec
INSERT INTO control.public_url_recovery_episodes (
    public_url_id,
    publish_run_number,
    state,
    opened_at
) VALUES (
    $1,
    $2,
    'open',
    $3
)
ON CONFLICT (public_url_id, publish_run_number) WHERE state = 'open' DO NOTHING
`

type OpenPublicURLRecoveryEpisodeParams struct {
	PublicURLID      string
	PublishRunNumber int64
	OpenedAt         pgtype.Timestamptz
}

func (q *Queries) OpenPublicURLRecoveryEpisode(ctx context.Context, arg OpenPublicURLRecoveryEpisodeParams) error {
	_, err := q.db.Exec(ctx, openPublicURLRecoveryEpisode, arg.PublicURLID, arg.PublishRunNumber, arg.OpenedAt)
	return err
}

const updatePublicURLRecoveryHistogram = `-- name: UpdatePublicURLRecoveryHistogram :one
UPDATE control.public_url_recovery_histogram
SET observation_count = observation_count + 1,
    observation_sum_seconds = observation_sum_seconds + $1,
    bucket_le_0_25 = bucket_le_0_25 + CASE WHEN $1 <= 0.25 THEN 1 ELSE 0 END,
    bucket_le_0_5 = bucket_le_0_5 + CASE WHEN $1 <= 0.5 THEN 1 ELSE 0 END,
    bucket_le_1 = bucket_le_1 + CASE WHEN $1 <= 1 THEN 1 ELSE 0 END,
    bucket_le_2 = bucket_le_2 + CASE WHEN $1 <= 2 THEN 1 ELSE 0 END,
    bucket_le_5 = bucket_le_5 + CASE WHEN $1 <= 5 THEN 1 ELSE 0 END,
    bucket_le_10 = bucket_le_10 + CASE WHEN $1 <= 10 THEN 1 ELSE 0 END,
    bucket_le_20 = bucket_le_20 + CASE WHEN $1 <= 20 THEN 1 ELSE 0 END,
    bucket_le_30 = bucket_le_30 + CASE WHEN $1 <= 30 THEN 1 ELSE 0 END,
    bucket_le_45 = bucket_le_45 + CASE WHEN $1 <= 45 THEN 1 ELSE 0 END,
    bucket_le_60 = bucket_le_60 + CASE WHEN $1 <= 60 THEN 1 ELSE 0 END,
    bucket_le_120 = bucket_le_120 + CASE WHEN $1 <= 120 THEN 1 ELSE 0 END,
    updated_at = $2
WHERE id = 1
RETURNING id, observation_count, observation_sum_seconds, bucket_le_0_25, bucket_le_0_5, bucket_le_1, bucket_le_2, bucket_le_5, bucket_le_10, bucket_le_20, bucket_le_30, bucket_le_45, bucket_le_60, bucket_le_120, updated_at
`

type UpdatePublicURLRecoveryHistogramParams struct {
	ObservedSeconds float64
	UpdatedAt       pgtype.Timestamptz
}

func (q *Queries) UpdatePublicURLRecoveryHistogram(ctx context.Context, arg UpdatePublicURLRecoveryHistogramParams) (ControlPublicUrlRecoveryHistogram, error) {
	row := q.db.QueryRow(ctx, updatePublicURLRecoveryHistogram, arg.ObservedSeconds, arg.UpdatedAt)
	var i ControlPublicUrlRecoveryHistogram
	err := row.Scan(
		&i.ID,
		&i.ObservationCount,
		&i.ObservationSumSeconds,
		&i.BucketLe025,
		&i.BucketLe05,
		&i.BucketLe1,
		&i.BucketLe2,
		&i.BucketLe5,
		&i.BucketLe10,
		&i.BucketLe20,
		&i.BucketLe30,
		&i.BucketLe45,
		&i.BucketLe60,
		&i.BucketLe120,
		&i.UpdatedAt,
	)
	return i, err
}
